package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	counts := map[string]int{}
	for scanner.Scan() {
		counts[scanner.Text()]++
	}
	// find the most frequent word and print it
	fmt.Println(len(counts))
}
